function queryRows(){const f=U.applied,match=(key,d)=>{const ids=Array.isArray(f[key])?f[key]:[f[key]].filter(Boolean);return !ids.length||ids.includes(d[key])};return S.docs.filter(d=>(!f.start||d.date.slice(0,10)>=f.start)&&(!f.end||d.date.slice(0,10)<=f.end)&&(!f.number||String(d.id).toLocaleLowerCase().includes(f.number.toLocaleLowerCase()))&&['customerId','warehouseId','salespersonId','storeId'].every(k=>match(k,d))&&match('status',{status:statusLabel(d)})&&match('businessType',{businessType:A.type(d)==='销售'?'销售':'退货/换货'})).sort((a,b)=>(Date.parse(b.updated)||0)-(Date.parse(a.updated)||0)||a.id.localeCompare(b.id))}

