function select(label,field,xs,value,ctx='doc'){const caption=`<span class="sale-field-label">${label}${ctx==='doc'?' <span class="ui-required">*</span>':''}</span>`,fieldClass=ctx==='doc'?' class="tc-gold-field"':'';if(ctx!=='filter'&&!canEdit()){const key={customerId:'customerName',salespersonId:'salespersonName',storeId:'storeName',settlementCustomerId:'settlementCustomerName',paymentMethodId:'paymentMethodName'}[field];return `<label${fieldClass}>${caption}<span class="sale-read-value">${h(U.doc[key]||xs.find(x=>x.id===value)?.name||'')}</span></label>`}if(field==='status')return `<label>${label}<select aria-label="筛选${label}" data-sale-field="${field}" data-context="${ctx}">${options(xs,value,'全部状态')}</select></label>`;return `<label${fieldClass}>${caption}<button type="button" class="btn entity-control${ctx==='doc'?' ui-single-flat':''}" data-sale-entity="${field}" data-context="${ctx}" aria-label="${ctx==='filter'?'筛选':''}${label}" title="${h(ENTITY_SELECT.text(xs,value,''))}">${h(ENTITY_SELECT.text(xs,value,ctx==='filter'?'全部'+label:'请选择'+label))}</button></label>`}

function salesFacts(d){return SALES_SUMMARY.project(d,[],D.products,C)}
function salesUnits(units){return Object.keys(units).length?K.unitText(units):'0'}

