 return `<span class="tc-product-tags" title="${h(categories.map(c=>c.name+' '+K.unitText(c.units)).join(' · '))}">${categories.slice(0,3).map(c=>`<span class="tc-product-tag">${h(c.name)} ${h(K.unitText(c.units))}</span>`).join('')}${categories.length>3?`<span class="tc-product-tag">+${categories.length-3} 更多</span>`:''}</span>`;
