document.addEventListener('input',e=>{const el=e.target;if(el.dataset.saleField==='note'&&canEdit()){U.doc.note=el.value;update();return}const entry=el.dataset.entry&&entries().find(x=>x.id===el.dataset.entry);if(!entry||!canEdit())return;const field=el.dataset.entryField;if(field==='product'){entry.query=el.value;entry.productId='';entry.c=null;entry.s=null;entry.quantity='';entry.price='';entry.gift=false;const row=el.closest('tr');row.querySelector('.sale-entry-name')?.remove();row.querySelectorAll('[data-entry-field]').forEach(x=>{if(x!==el){x.disabled=true;if(x.type==='checkbox')x.checked=false;else x.value=''}});for(const i of [4,5,6,7,8])row.children[i].textContent='';update();if(!U.inlineComposing)searchEntry(entry,el)}else if(field==='quantity'||field==='price'){entry[field]=el.value;if(field==='quantity')el.classList.toggle('negative',Number(entry.quantity)<0);update();const row=el.closest('tr'),amount=row.children[8],ref=row.querySelector('[data-discount-ref]'),line=entryDoc().lines.find(l=>l.id===entry.lineId);if(ref)ref.value=line?.referenceCents>0&&K.cents(entry.price)!=null?discountText({...line,priceCents:K.cents(entry.price)}):'';amount.textContent=K.cents(entry.price)==null?'':K.money(Number(entry.quantity)*(entry.gift?0:K.cents(entry.price)))}});
