function validationError(message){
 U.error=message;
 const alert=$('#sale-error');if(alert)alert.textContent=message;
 document.querySelectorAll('.sale-editor .field-error[data-validation]').forEach(el=>el.remove());
 if(/单据日期/.test(message)){document.querySelector('[data-sales-date="document"]')?.shadowRoot?.querySelector('input')?.focus();return}
 const special=/优惠/.test(message)?'[data-document-adjustment]':/业务类型/.test(message)?'[data-sale-field=businessType]':/账户|方式/.test(message)?'[data-funds-field] select':/金额.*一致|收款金额/.test(message)?'[data-funds-field] [data-rf=amount]':null;
 if(special){$(special)?.focus();return}
 const min=K.minimumPriceIssue(U.doc,U.doc.lines.map(l=>p(l.productId)).filter(Boolean),S.docs.find(d=>d.id===U.doc.id));
 if(min&&/最低/.test(message)){$(`[data-line-price="${CSS.escape(min.lineId)}"]`)?.focus();return}
 const missing=!U.doc.storeId?'storeId':!S.catalog.customers.some(x=>x.id===U.doc.customerId)?'customerId':!S.session.warehouses.includes(U.doc.warehouseId)?'warehouseId':!S.catalog.staff.some(x=>x.id===U.doc.salespersonId)?'salespersonId':null;
 if(missing){$(`[data-sale-entity="${missing}"]`)?.focus();return}
 const row=entryDoc().lines.find(l=>!Number.isSafeInteger(l.quantity)||l.quantity===0||Math.abs(l.quantity)>99999||l.priceCents===null||U.priceErrors[l.id]);
 if(row){const field=!Number.isSafeInteger(row.quantity)||row.quantity===0||Math.abs(row.quantity)>99999?'qty':'price';$(`[data-line-${field}="${CSS.escape(row.id)}"]`)?.focus()}
 stash();
}
function impactSummary(old,next){const before=K.totals(old),after=next?K.totals(next):{units:{},total:0},warehouses=new Set([old.warehouseId,next?.warehouseId].filter(Boolean));const stock=[...warehouses].map(w=>{const units={};if(old.warehouseId===w)for(const [u,n]of Object.entries(before.units))units[u]=(units[u]||0)+n;if(next?.warehouseId===w)for(const [u,n]of Object.entries(after.units))units[u]=(units[u]||0)-n;return Object.entries(units).filter(([,n])=>n).map(([u,n])=>wh(w)+'库存'+(n>0?'恢复':'扣减')+Math.abs(n)+u).join('；')}).filter(Boolean).join('；');return h('销售数量 '+K.unitText(before.units)+' → '+K.unitText(after.units)+'；'+(stock||'库存总量不变（规格变化见明细）')+'；成交金额 '+K.money(before.total)+' → '+K.money(after.total))}
S.ready.then(r=>{U.ready=r.ok;U.error=r.ok?'':r.error;if(r.ok){try{const stored=JSON.parse(sessionStorage.getItem('sales-work:'+TRANSFER_SERVICE.key+':'+(S.session?.accountId||S.actor?.id||'legacy'))||'null');const route=location.hash.slice(1),resumeNew=route==='sales/new'&&stored?.doc?.revision===0,resumeDoc=route==='sales/doc/'+encodeURIComponent(stored?.doc?.id||'');if(stored?.editing&&(resumeNew||resumeDoc)){Object.assign(U,stored);U.scanOpen=false;hydrateEntries()}else if(S.fixture&&route==='sales/new'){const n=Number(new URLSearchParams(location.search).get('sale-sample'));if(n===1||n===2)setDoc(S.sample(n),true)}}catch{}}window.render()});
document.addEventListener('click',async e=>{
 const el=e.target.closest('[data-sale-entity]');if(!el)return;
 const field=el.dataset.saleEntity,ctx=el.dataset.context,historical=ctx==='filter',target=historical?U.filter:ctx==='more'?U.moreDraft:U.doc;
 if(!target||!historical&&!canEdit())return;
 let recommended=null;
 if(field==='customerId'&&!historical){const hall=U.doc.storeId;let historicalChoice=null;try{historicalChoice=(await window.LEGACY_REAL?.ensureRecommendations?.(hall))?.customerId}catch{}const eligible=id=>S.catalog.customers.some(x=>x.id===id&&x.enabled!==false&&(x.usage||x.tags||[]).includes('customer'));const fallback=S.catalog.stores.find(x=>x.id===hall)?.defaultCustomerId;recommended=eligible(historicalChoice)?historicalChoice:eligible(fallback)?fallback:null}
 ENTITY_SELECT.open(el,{label:el.getAttribute('aria-label')||el.closest('label').textContent.trim(),items:()=>entityItems(field,historical),multiple:historical,allIsUnfiltered:historical,value:target[field],allowClear:historical,flatValue:!historical,recommendation:recommended?{id:recommended}:null,onConfirm:id=>{
  if(historical){target[field]=id;return refresh()}
  if(!id)return;
  BUSINESS_CONFIG.assign(target,field,id,S.catalog);
   if(field==='storeId'){
   window.LEGACY_REAL?.ensureRecommendations?.(id).catch(()=>{});
   if(!entityItems('salespersonId').some(x=>x.id===target.salespersonId))target.salespersonId='';
   const allowed=saleWarehouses(id);
   const preferred=S.catalog.stores.find(x=>x.id===id)?.defaultWarehouseId;
   if(preferred&&allowed.some(x=>x.id===preferred))target.warehouseId=preferred;
   else if(!allowed.some(x=>x.id===target.warehouseId))target.warehouseId='';
   SALES_FUNDS_UI.reconcile?.(target);
   try{localStorage.setItem('sales-store:'+TRANSFER_SERVICE.key+':'+S.session.accountId,id)}catch{}
  }
  if(ctx==='more'){el.textContent=ENTITY_SELECT.text(entityItems(field),id,'请选择');return}
  update();refresh();
 }});
});
